head.b:skin:
/*
  GuideNest Theme for Blogger
  Clean evidence-style guide theme. No external fonts, no frameworks.
  Navy #0A1F33 + white, single accent #0F766E.
*/
:root{--navy:#0A1F33;--accent:#0F766E;--accent-d:#0B5C56;--ink:#16222f;--muted:#5b6b7a;--line:#e2e8ef;--soft:#f4f7fa;--r:10px}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:#fff;color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.skip{position:absolute;left:-999px;top:0;background:#fff;color:var(--navy);padding:8px 12px;z-index:100}
.skip:focus{left:8px;top:8px}
.wrap{max-width:1140px;margin:0 auto;padding:0 20px}
.section{margin:0;padding:0}
.section .widget{margin:0}

/* Header */
#site-header{position:sticky;top:0;z-index:50;background:var(--navy);color:#fff;box-shadow:0 1px 0 rgba(255,255,255,.08)}
#site-header .bar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:12px;padding-bottom:8px}
.brand a{color:#fff;font-size:1.45rem;font-weight:800;letter-spacing:-.02em;text-decoration:none}
.brand a span{color:#7fd6cc}
.brand .site-title{margin:0;font-size:inherit;line-height:1.2}
.search{display:flex;min-width:0}
.search input[type=search]{width:210px;max-width:100%;padding:8px 12px;border:1px solid rgba(255,255,255,.25);border-right:0;border-radius:8px 0 0 8px;background:rgba(255,255,255,.1);color:#fff;font:inherit;font-size:.95rem}
.search input::placeholder{color:#b8c6d3}
.search button{padding:8px 14px;border:0;border-radius:0 8px 8px 0;background:var(--accent);color:#fff;font:inherit;font-weight:600;cursor:pointer}
.search button:hover{background:var(--accent-d)}
.primary{overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.primary::-webkit-scrollbar{display:none}
.primary ul{display:flex;gap:2px;margin:0;padding:0 0 6px;list-style:none;white-space:nowrap}
.primary a{display:block;padding:8px 14px;border-radius:8px;color:#dbe5ee;font-weight:600;font-size:.95rem;text-decoration:none}
.primary a:hover{background:rgba(255,255,255,.12);color:#fff}

/* Layout */
.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:44px;padding-top:32px;padding-bottom:48px}
#sidebar .widget{margin:0 0 28px;padding:20px;border:1px solid var(--line);border-radius:var(--r);background:#fff}
#sidebar h3{margin:0 0 12px;font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;color:var(--navy)}
#sidebar ul{margin:0;padding:0;list-style:none}
#sidebar li{padding:8px 0;border-top:1px solid var(--line)}
#sidebar li:first-child{border-top:0;padding-top:0}
#sidebar .pop{display:flex;gap:12px;align-items:flex-start}
#sidebar .pop img{width:60px;height:60px;object-fit:cover;border-radius:8px;flex:none}
#sidebar .pop a{color:var(--ink);font-weight:600;line-height:1.35}
#sidebar .count{color:var(--muted);font-size:.85rem}
#sidebar p{margin:0;color:var(--muted);font-size:.95rem}

/* Home & archive */
.page-title{margin:0 0 20px;font-size:1.8rem;line-height:1.25;color:var(--navy)}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:24px}
.card{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#fff;transition:box-shadow .2s}
.card:hover{box-shadow:0 6px 20px rgba(10,31,51,.09)}
.card .thumb{display:block;aspect-ratio:16/9;background:var(--soft)}
.card .thumb img{width:100%;height:100%;object-fit:cover;display:block}
.card .body{padding:16px 18px 20px;display:flex;flex-direction:column;gap:8px;flex:1}
.card .tag{font-size:.75rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.card h2{margin:0;font-size:1.15rem;line-height:1.3}
.card h2 a{color:var(--navy)}
.card p{margin:0;color:var(--muted);font-size:.95rem}
.card .more{margin-top:auto;font-weight:700;font-size:.92rem}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:32px}
.btn{display:inline-block;padding:11px 20px;border-radius:8px;background:var(--accent);color:#fff;font-weight:700;text-decoration:none}
.btn:hover{background:var(--accent-d);text-decoration:none;color:#fff}

/* Post */
.crumbs{margin:0 0 14px;font-size:.88rem;color:var(--muted)}
.crumbs a{color:var(--muted)}
.crumbs span.sep{margin:0 6px}
.post h1{margin:0 0 10px;font-size:2.1rem;line-height:1.2;letter-spacing:-.02em;color:var(--navy)}
.post .meta{margin:0 0 24px;color:var(--muted);font-size:.92rem;display:flex;flex-wrap:wrap;gap:6px 14px}
.post .meta a{color:var(--accent);font-weight:600}
.post-body{font-size:1.125rem;line-height:1.7;max-width:760px;overflow-wrap:break-word}
.post-body h2{margin:2.1em 0 .6em;font-size:1.6rem;line-height:1.3;color:var(--navy);padding-bottom:.3em;border-bottom:2px solid var(--line);scroll-margin-top:120px}
.post-body h3{margin:1.8em 0 .5em;font-size:1.28rem;line-height:1.35;color:var(--navy);scroll-margin-top:120px}
.post-body p{margin:0 0 1.15em}
.post-body ul,.post-body ol{margin:0 0 1.2em;padding-left:1.4em}
.post-body li{margin:.35em 0}
.post-body a{text-decoration:underline;text-underline-offset:2px}
.post-body blockquote{margin:1.4em 0;padding:.6em 1.1em;border-left:4px solid var(--accent);background:var(--soft);border-radius:0 8px 8px 0}
.post-body table{display:block;overflow-x:auto;border-collapse:collapse;width:100%;margin:1.4em 0;font-size:.98rem}
.post-body th,.post-body td{padding:10px 12px;border:1px solid var(--line);text-align:left}
.post-body th{background:var(--soft);color:var(--navy)}
.post-body .separator a{text-decoration:none}
.toc{margin:1.6em 0;padding:14px 18px;border:1px solid var(--line);border-radius:var(--r);background:var(--soft);font-size:1rem}
.toc summary{cursor:pointer;font-weight:800;color:var(--navy)}
.toc ol{margin:10px 0 0;padding-left:1.3em}
.toc li{margin:.3em 0}
.toc li.sub{margin-left:1em;list-style:circle}
.labels{margin:28px 0 0;display:flex;flex-wrap:wrap;gap:8px}
.labels a{padding:4px 12px;border:1px solid var(--line);border-radius:999px;font-size:.85rem;font-weight:600;color:var(--navy)}
.labels a:hover{background:var(--soft);text-decoration:none}
.prevnext{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:36px 0}
.prevnext a{display:block;padding:14px 16px;border:1px solid var(--line);border-radius:var(--r);color:var(--navy);font-weight:700;line-height:1.35}
.prevnext a small{display:block;margin-bottom:4px;color:var(--accent);font-size:.75rem;letter-spacing:.06em;text-transform:uppercase}
.prevnext .next{text-align:right;grid-column:2}
.prevnext a:hover{background:var(--soft);text-decoration:none}
.related h2,.comments h2{margin:0 0 16px;font-size:1.35rem;color:var(--navy)}
.related{margin-top:36px}
.related .cards{grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px}
.related .card h3{margin:0;font-size:1rem;line-height:1.3}
.related .card h3 a{color:var(--navy)}
.comments{margin-top:44px}
.comments ol{list-style:none;margin:0 0 20px;padding:0}
.comments li{padding:14px 0;border-top:1px solid var(--line)}
.comments li span{color:var(--muted);font-size:.85rem;margin-left:8px}
.comments iframe{border:0}
.ad-slot{margin:24px auto;text-align:center;max-width:100%;overflow:hidden}
.ad-slot:empty{display:none}

/* Footer */
#site-footer{background:var(--navy);color:#b8c6d3;padding:32px 0;font-size:.92rem}
#site-footer a{color:#fff}
#site-footer ul{display:flex;flex-wrap:wrap;gap:8px 22px;margin:0 0 16px;padding:0;list-style:none}
#site-footer p{margin:4px 0}

@media(max-width:900px){
  .layout{grid-template-columns:1fr;gap:12px}
}
@media(max-width:600px){
  .wrap{padding:0 16px}
  .brand a{font-size:1.25rem}
  #site-header .bar{flex-wrap:wrap;gap:8px;padding-top:10px}
  .search{width:100%}
  .search input[type=search]{flex:1;width:auto}
  .layout{padding-top:20px}
  .post h1{font-size:1.7rem}
  .post-body h2{font-size:1.4rem}
  .cards{grid-template-columns:1fr}
  .related .cards{grid-template-columns:1fr 1fr}
  .prevnext{grid-template-columns:1fr}
  .prevnext .next{grid-column:1;text-align:left}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.card{transition:none}}
.widget-content{margin:0}
.clear{clear:both}

body.script:
//
(function(){
  var d=document,body=d.querySelector('.post-body');
  if(!body)return;
  var isPost=!!d.getElementById('related');
  var hs=body.querySelectorAll('h2,h3');

  /* Table of contents (built in the browser, post content is never modified in Blogger) */
  if(isPost&&hs.length>=3){
    var det=d.createElement('details'),sum=d.createElement('summary'),ol=d.createElement('ol');
    det.className='toc';det.open=true;sum.textContent='Table of contents';det.appendChild(sum);
    for(var i=0;i<hs.length;i++){
      var h=hs[i];
      if(!h.id)h.id='sec-'+(i+1);
      var li=d.createElement('li'),a=d.createElement('a');
      a.href='#'+h.id;a.textContent=h.textContent;
      if(h.tagName==='H3')li.className='sub';
      li.appendChild(a);ol.appendChild(li);
    }
    det.appendChild(ol);
    hs[0].parentNode.insertBefore(det,hs[0]);
  }

  /* Move in-content ad slot before the 2nd heading (stays hidden while empty) */
  var slot=d.getElementById('ad-incontent');
  if(slot&&hs.length>1)hs[1].parentNode.insertBefore(slot,hs[1]);

  if(!isPost)return;

  /* Related posts from the same label via the public Blogger feed */
  var rel=d.getElementById('related'),lab=d.querySelector('.first-label');
  var feed=location.origin+'/feeds/posts/summary';
  var url=feed+(lab?'/-/'+encodeURIComponent(lab.textContent):'')+'?alt=json&max-results=8';
  fetch(url).then(function(r){return r.json()}).then(function(j){
    var es=(j.feed&&j.feed.entry)||[],box=rel.querySelector('.cards'),n=0;
    es.forEach(function(e){
      if(n>=4)return;
      var href='';(e.link||[]).forEach(function(l){if(l.rel==='alternate')href=l.href});
      if(!href||href===location.href)return;
      var c=d.createElement('article'),b=d.createElement('div'),h=d.createElement('h3'),a=d.createElement('a');
      c.className='card';b.className='body';
      if(e.media$thumbnail){
        var t=d.createElement('a'),im=d.createElement('img');
        t.className='thumb';t.href=href;t.tabIndex=-1;
        im.src=e.media$thumbnail.url.replace(/\/s\d+(-c)?\//,'/w400-h225-c/');
        im.alt='';im.loading='lazy';im.width=400;im.height=225;
        t.appendChild(im);c.appendChild(t);
      }
      a.href=href;a.textContent=e.title.$t;h.appendChild(a);b.appendChild(h);c.appendChild(b);
      box.appendChild(c);n++;
    });
    if(n)rel.hidden=false;
  }).catch(function(){});

  /* Article structured data (JSON-LD), dates from the post feed */
  var h1=d.querySelector('.post h1'),can=d.querySelector('link[rel=canonical]');
  var og=d.querySelector('meta[property="og:image"]'),im0=body.querySelector('img');
  var ld={"@context":"https://schema.org","@type":"Article",
    "headline":h1?h1.textContent:d.title,
    "mainEntityOfPage":{"@type":"WebPage","@id":can?can.href:location.href},
    "publisher":{"@type":"Organization","name":"GuideNest USA"}};
  var img=og?og.content:(im0?im0.src:'');
  if(img)ld.image=[img];
  function emit(){var s=d.createElement('script');s.type='application/ld+json';s.text=JSON.stringify(ld);d.head.appendChild(s)}
  var full=feed.replace('/summary','/default')+(lab?'/-/'+encodeURIComponent(lab.textContent):'')+'?alt=json&max-results=50';
  fetch(full).then(function(r){return r.json()}).then(function(j){
    var es=(j.feed&&j.feed.entry)||[];
    for(var k=0;k<es.length;k++){
      var e=es[k],href='';
      (e.link||[]).forEach(function(l){if(l.rel==='alternate')href=l.href});
      if(href===location.href){ld.datePublished=e.published.$t;ld.dateModified=e.updated.$t;
        if(e.author&&e.author[0])ld.author={"@type":"Person","name":e.author[0].name.$t};
        break;}
    }
    emit();
  }).catch(emit);
})();
//
